CREATE TABLE `payment_gateway_configs` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`provider` VARCHAR(64) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT false,`environment` ENUM('SANDBOX', 'PRODUCTION') NOT NULL DEFAULT 'SANDBOX',`credentials_ciphertext` TEXT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `payment_gateway_configs_public_id_key` (`public_id`),UNIQUE INDEX `payment_gateway_configs_tenant_id_key` (`tenant_id`),CONSTRAINT `payment_gateway_configs_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `payment_gateway_charges` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`appointment_id` BIGINT UNSIGNED NOT NULL,`payment_id` BIGINT UNSIGNED NULL,`provider` VARCHAR(64) NOT NULL,`environment` ENUM('SANDBOX', 'PRODUCTION') NOT NULL,`external_id` VARCHAR(191) NULL,`status` ENUM('PENDING', 'PROCESSING', 'PAID', 'FAILED', 'CANCELED', 'EXPIRED', 'REFUNDED') NOT NULL DEFAULT 'PENDING',`amount_cents` BIGINT UNSIGNED NOT NULL,`currency` CHAR(3) NOT NULL,`idempotency_key` VARCHAR(191) NOT NULL,`last_checked_at` DATETIME(3) NULL,`canceled_at` DATETIME(3) NULL,`canceled_reason` VARCHAR(500) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `payment_gateway_charges_public_id_key` (`public_id`),UNIQUE INDEX `payment_gateway_charges_payment_id_key` (`payment_id`),UNIQUE INDEX `payment_gateway_charges_tenant_id_idempotency_key_key` (`tenant_id`,`idempotency_key`),INDEX `payment_gateway_charges_tenant_id_appointment_id_idx` (`tenant_id`,`appointment_id`),INDEX `payment_gateway_charges_tenant_id_status_idx` (`tenant_id`,`status`),INDEX `payment_gateway_charges_tenant_id_provider_external_id_idx` (`tenant_id`,`provider`,`external_id`),CONSTRAINT `payment_gateway_charges_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `payment_gateway_charges_appointment_id_fkey` FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `payment_gateway_charges_payment_id_fkey` FOREIGN KEY (`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `payment_gateway_events` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`charge_id` BIGINT UNSIGNED NULL,`provider` VARCHAR(64) NOT NULL,`direction` ENUM('OUTBOUND', 'INBOUND') NOT NULL,`event_type` VARCHAR(80) NOT NULL,`external_event_id` VARCHAR(191) NULL,`payload` JSON NULL,`status_code` SMALLINT UNSIGNED NULL,`success` BOOLEAN NOT NULL,`error_message` VARCHAR(1000) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `payment_gateway_events_public_id_key` (`public_id`),UNIQUE INDEX `payment_gateway_events_tenant_id_provider_external_event_id_key` (`tenant_id`,`provider`,`external_event_id`),INDEX `payment_gateway_events_tenant_id_charge_id_created_at_idx` (`tenant_id`,`charge_id`,`created_at`),CONSTRAINT `payment_gateway_events_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `payment_gateway_events_charge_id_fkey` FOREIGN KEY (`charge_id`) REFERENCES `payment_gateway_charges`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
